python3  - <<'PY'
import glob
import json
from collections import defaultdict

selection = json.load(open('selected.json'))
meta = {p['arxivId']: p for p in selection['papers']}
window = selection['window']

rows, bad = [], 0
for path in sorted(glob.glob('rows/*.jsonl')):
    for line in open(path, errors='ignore'):
        line = line.strip()
        if not line:
            continue
        try:
            rec = json.loads(line)
        except json.JSONDecodeError:
            bad += 1
            continue
        if rec.get('kind') in ('score', 'benchmark'):
            rows.append(rec)

benchmarks, models = {}, {}
scores = defaultdict(lambda: defaultdict(list))
seen = set()

for r in rows:
    aid = (r.get('paper') or '').strip()
    bench = ' '.join((r.get('benchmark') or '').split())
    if not aid or not bench:
        continue
    benchmarks.setdefault(bench, {'papers': set()})['papers'].add(aid)
    if r.get('kind') != 'score':
        continue
    model = ' '.join((r.get('model') or '').split())
    score = ' '.join(str(r.get('score') or '').split())
    if not model or not score:
        continue
    metric = ' '.join((r.get('metric') or '').split())
    key = (aid, model.lower(), bench.lower(), score, metric.lower())
    if key in seen:
        continue
    seen.add(key)
    models.setdefault(model, {'papers': set(), 'cells': 0})['papers'].add(aid)
    models[model]['cells'] += 1
    scores[model][bench].append((score, metric, aid))


def cell(model, bench):
    out, used = [], set()
    for score, metric, _ in scores[model].get(bench, []):
        text = f'{score} {metric}'.strip()
        if text.lower() not in used:
            used.add(text.lower())
            out.append(text)
    return '; '.join(out)


def esc(text):
    return text.replace('|', '\\|').replace('\n', ' ')


def coverage(bench):
    return sum(1 for m in scores if bench in scores[m])


bench_sorted = sorted(benchmarks, key=lambda b: (-coverage(b), b.lower()))
models_sorted = sorted(models, key=lambda m: (-models[m]['cells'], m.lower()))

lines = [
    f'# Model benchmark scores from arXiv ({window[0]} to {window[1]})',
    '',
    f'Papers: {len(meta)} · models: {len(models)} · benchmarks: {len(bench_sorted)} · score rows: {len(seen)}',
    '',
    '| Model | ' + ' | '.join(esc(b) for b in bench_sorted) + ' |',
    '| --- | ' + ' | '.join('---' for _ in bench_sorted) + ' |',
]
for m in models_sorted:
    lines.append('| ' + esc(m) + ' | ' + ' | '.join(esc(cell(m, b)) for b in bench_sorted) + ' |')

lines += ['', '## Source papers', '', '| arXiv | Citations | Focus | Title |', '| --- | --- | --- | --- |']
for p in sorted(meta.values(), key=lambda p: -p['citationCount']):
    tag = p.get('focus') if p.get('focus') in ('open', 'closed') else 'mixed'
    lines.append(f"| [{p['arxivId']}](https://arxiv.org/abs/{p['arxivId']}) | {p['citationCount']} | {tag} | {esc(p['title'])} |")

lines += [
    '', '## Notes', '',
    f'- Window: {window[0]} to {window[1]} (90 days).',
    '- Inclusion: arXiv paper, at least 10 Semantic Scholar citations at selection time, benchmark or systematic evaluation of language models.',
    '- An empty cell means no paper in the set reported that model on that benchmark. Several values in one cell mean the model was reported under more than one setting or metric.',
    f'- {bad} malformed extraction line(s) were skipped.',
]
open('table.md', 'w').write('\n'.join(lines) + '\n')

print(f'STATS papers={len(meta)} models={len(models)} benchmarks={len(bench_sorted)} score_rows={len(seen)} skipped={bad}')
for b in bench_sorted:
    vals = []
    for m, by_bench in scores.items():
        for score, metric, _ in by_bench.get(b, []):
            try:
                vals.append((float(score.rstrip('%')), m, metric))
            except ValueError:
                pass
    if vals:
        best = max(vals)
        print(f'SATURATION {b} | models={coverage(b)} | best={best[0]} by {best[1]} ({best[2]})')
    else:
        print(f'SATURATION {b} | models={coverage(b)} | best=NA')
for m in sorted(models, key=lambda m: -models[m]['cells'])[:8]:
    print(f'COVERAGE {m} | benchmarks={len(scores[m])} | papers={len(models[m]["papers"])}')

